  // Validation des paramètres
  const input = $input.first().json;
  const body = input.body || input;

  const traite = body.traite || '';
  const page = body.page || '';
  const mode = body.mode || 'premium';
  const targetLanguage = body.target_language || 'fr';
  const apiKey = body.api_key || '';
  const openaiApiKey = body.openai_api_key || '';
  const requestId = body.request_id || null;
  const force = body.force === true || body.force === 'true';
  const corpus = body.corpus || null;
  const headers = input.headers || {};
  // Extraire projectId depuis le HEADER ou le body
  const projectId = headers['x-project-id'] || body.project_id || body.projectId;
  const jobType = body.job_type || body.jobType;

  // Validation
  const errors = [];
  if (!traite) errors.push('Le champ "traite" est requis');
  if (!page) errors.push('Le champ "page" est requis');
  if (!apiKey) errors.push('Le champ "api_key" (Anthropic) est requis');
  if (!openaiApiKey) errors.push('Le champ "openai_api_key" est requis');
  if (!jobType) errors.push('Le champ "job_type" est requis');

// Générer un job_id unique
  const jobId = 'job_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);

  return [{
    json: {
      valid: errors.length === 0,
      errors: errors,
      jobId: jobId,
      jobType: jobType,  // ← AJOUTER,
      projectId: projectId,
      traite: traite,
      page: page,
      mode: mode,
      targetLanguage: targetLanguage,
      apiKey: apiKey,
      openaiApiKey: openaiApiKey,
      requestId: requestId,
      force: force,
      corpus: corpus
    }
  }];

// Analyser les traductions existantes
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Si erreur API (page non trouvée), continuer vers la traduction
if (statusCode >= 400) {
  return [{
    json: {
      ...prevData,
      hasExisting: false,
      needsTranslation: true
    }
  }];
}

const segmentsCount = data.segments_count || 0;
const translatedCount = data.translated_count || 0;
const isFullyTranslated = segmentsCount > 0 && translatedCount === segmentsCount;

// Si force=true, toujours retraduire
if (prevData.force) {
  return [{
    json: {
      ...prevData,
      hasExisting: isFullyTranslated,
      needsTranslation: true
    }
  }];
}

// Si déjà traduit et pas force, retourner les existantes
if (isFullyTranslated) {
  return [{
    json: {
      ...prevData,
      hasExisting: true,
      needsTranslation: false,
      existingData: data
    }
  }];
}

// Sinon, besoin de traduire
return [{
  json: {
    ...prevData,
    hasExisting: false,
    needsTranslation: true,
    existingSegmentsCount: segmentsCount,
    existingTranslatedCount: translatedCount
  }
}];

// Formater la réponse pour les traductions existantes
const input = $input.first().json;
const data = input.existingData;

return [{
  json: {
    success: true,
    status: 'already_translated',
    traite: data.traite,
    page: data.page,
    reference: data.reference,
    segments_count: data.segments_count,
    translated_count: data.translated_count,
    segments: data.segments
  }
}];

// Extraire les segments de la page (API v2 - segments with segment_id + reference_translation)
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Vérifier les erreurs (API v2: AmbiguousReferenceError)
if (statusCode >= 400 || data.error) {
  const isAmbiguous = data.error?.code === 'AmbiguousReferenceError';
  return [{
    json: {
      success: false,
      error: {
        code: isAmbiguous ? 'AMBIGUOUS_REFERENCE' : statusCode,
        message: data.error?.message || data.message || 'Page non trouvée',
        status: isAmbiguous ? 'AMBIGUOUS_REFERENCE' : 'PAGE_NOT_FOUND',
        options: data.error?.options || null
      }
    }
  }];
}

// Extraire les segments (API v2: objets avec segment_id)
let rawSegments = [];
if (data.extra_data?.versions?.[0]?.text) {
  rawSegments = data.extra_data.versions[0].text;
} else if (data.segments) {
  rawSegments = data.segments;
}

// Normaliser: accepter string[] ou {segment_id, text, reference_translation}[]
// RFC bilingual-translations-en-pivot: extraire reference_translation pour EN-pivot
const segments = rawSegments.map((seg, idx) => {
  if (typeof seg === 'string') {
    return { index: idx, text: seg, segment_id: null, reference_translation: null };
  }
  return {
    index: seg.index !== undefined ? seg.index : idx,
    text: seg.text || seg.hebrew_text || '',
    segment_id: seg.segment_id || null,
    // RFC: reference_translation = traduction EN Sefaria/Koren (pivot)
    reference_translation: seg.reference_translation?.translated_text || null
  };
});

if (segments.length === 0) {
  return [{
    json: {
      success: false,
      error: {
        code: 404,
        message: 'Aucun segment trouvé pour cette page',
        status: 'NO_SEGMENTS'
      }
    }
  }];
}

const estimatedSeconds = Math.ceil(segments.length * 7);
const hasReferenceTranslations = segments.some(s => s.reference_translation);

return [{
  json: {
    success: true,
    jobId: prevData.jobId,
    jobType: prevData.jobType,
    projectId: prevData.projectId,
    corpus: data.corpus || null,
    traite: prevData.traite,
    page: prevData.page,
    mode: prevData.mode,
    targetLanguage: prevData.targetLanguage,
    apiKey: prevData.apiKey,
    openaiApiKey: prevData.openaiApiKey,
    requestId: prevData.requestId,
    sourceTextId: data.id || null,
    reference: data.reference || `${prevData.traite} ${prevData.page}`,
    segments: segments,
    segmentsCount: segments.length,
    estimatedSeconds: estimatedSeconds,
    hasSegmentIds: segments.some(s => s.segment_id),
    hasReferenceTranslations: hasReferenceTranslations
  }
}];

// Extraire le job_id de la réponse API
const input = $input.first().json;
const prevData = $('Extract Segments').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

if (statusCode >= 400 || data.error) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.error?.message || data.message || 'Erreur création job',
        status: 'JOB_CREATION_ERROR'
      }
    }
  }];
}

return [{
  json: {
    ...prevData,
     jobId: data.job_id || data.jobId,
    jobCreated: true
  }
}];

// Préparer le payload pour le Torah Router (API v2 - segment_id + reference_translation)
const data = $input.first().json;

// Formater les segments pour le Router (API v2: inclure segment_id + reference_translation)
// RFC bilingual-translations-en-pivot: propager reference_translation pour EN-pivot
const formattedSegments = data.segments.map((seg, idx) => {
  const segment = typeof seg === 'string' ? { text: seg, index: idx } : seg;
  return {
    text: segment.text,
    segment_id: segment.segment_id || null,
    index: segment.index !== undefined ? segment.index : idx,
    // RFC: EN pivot pour améliorer qualité traduction
    reference_translation: segment.reference_translation || null
  };
});

return [{
  json: {
    routerPayload: {
      job_id: data.jobId,
      job_type: data.jobType || 'page_translation',
      segments: formattedSegments,
      source_language: 'he',
      target_language: data.targetLanguage,
      api_key: data.apiKey,
      openai_api_key: data.openaiApiKey,
      traite: data.traite,
      page: data.page,
      corpus: data.corpus,
      context: {
        traite: data.traite,
        page: data.page,
        reference: data.reference,
        mode: data.mode,
        corpus: data.corpus
      },
      metadata: {
        reference: data.reference,
        request_id: data.requestId,
        has_segment_ids: data.hasSegmentIds,
        has_reference_translations: data.hasReferenceTranslations
      }
    },
    jobId: data.jobId,
    traite: data.traite,
    page: data.page,
    segmentsCount: data.segmentsCount,
    estimatedSeconds: data.estimatedSeconds
  }
}];

// Préparer la réponse immédiate
const input = $('Prepare Worker Payload').first().json;

return [{
  json: {
    success: true,
    job_id: input.jobId,
    status: 'started',
    traite: input.traite,
    page: input.page,
    segments_count: input.segmentsCount,
    estimated_seconds: input.estimatedSeconds
  }
}];

// Construire la réponse d'erreur de validation
const input = $input.first().json;

return [{
  json: {
    success: false,
    error: {
      code: 400,
      message: input.errors.join(', '),
      status: 'BAD_REQUEST'
    }
  }
}];

